const currencyFmt = new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'});
const fmtDate = d => new Intl.DateTimeFormat('pt-PT',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00'));
const monthName = (y,m) => new Intl.DateTimeFormat('pt-PT',{month:'long',year:'numeric'}).format(new Date(y,m,1)).replace(/^./,c=>c.toUpperCase());
const uid=()=>crypto.randomUUID?.() || (Date.now()+'-'+Math.random());
const today=()=>new Date().toISOString().slice(0,10);
const monthKey=d=>d.slice(0,7);

const DEFAULT_CATEGORIES = [
['Supermercado','🛒','#dff4eb'],['Restaurantes','🍽️','#ffe7dd'],['Casa','🏠','#fff0c7'],['Contas','💡','#fff7d8'],['Transportes','🚗','#e3f1fb'],['Compras','🛍️','#f0e7f6'],['Tecnologia','💻','#e8edf9'],['Lazer','🎭','#fde6ef'],['Viagens','✈️','#e8f6f6'],['Saúde','❤️','#dff4ef'],['Desporto','🏋️','#e6f4e8'],['Cuidados pessoais','💇','#fbe8ef'],['Subscrições','📺','#ece8f7'],['Educação','🎓','#e6eff9'],['Presentes','🎁','#ffe9d9'],['Impostos e taxas','💰','#f2ece7'],['Outros','📦','#efefef']
].map(([name,emoji,color])=>({id:uid(),name,emoji,color,type:'expense',archived:false}));
const INCOME_CATEGORIES=[['Salário','💼'],['Trabalho extra','🧑‍💻'],['Investimentos','📈'],['Rendas','🏠'],['Presentes','🎁'],['Outros rendimentos','💰']].map(([name,emoji])=>({id:uid(),name,emoji,color:'#e6f6ef',type:'income',archived:false}));
const DEFAULT_ACCOUNTS=[{id:uid(),name:'Conta Principal',emoji:'🏦',monthlyGoal:null},{id:uid(),name:'Revolut',emoji:'💳',monthlyGoal:500}];

class DB{
  constructor(){this.db=null}
  open(){return new Promise((res,rej)=>{const r=indexedDB.open('financasPastel',2);r.onupgradeneeded=e=>{const d=e.target.result;['transactions','accounts','categories','tags','plans','settings','rules'].forEach(s=>{if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:'id'})})};r.onsuccess=()=>{this.db=r.result;res()};r.onerror=()=>rej(r.error)})}
  all(store){return new Promise((res,rej)=>{const r=this.db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
  put(store,obj){return new Promise((res,rej)=>{const r=this.db.transaction(store,'readwrite').objectStore(store).put(obj);r.onsuccess=()=>res(obj);r.onerror=()=>rej(r.error)})}
  del(store,id){return new Promise((res,rej)=>{const r=this.db.transaction(store,'readwrite').objectStore(store).delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
  clear(store){return new Promise((res,rej)=>{const r=this.db.transaction(store,'readwrite').objectStore(store).clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
}
const db=new DB();
const state={tab:'month',date:new Date(),tx:[],accounts:[],categories:[],tags:[],plans:[],rules:[],settings:{pinEnabled:false,pinHash:'',hideValues:false,alert75:true,alert90:true,alertOver:true,notificationsEnabled:false,autoLockMinutes:0,defaultPlan:null},expandedCat:null,filter:'all',search:'',advFilter:{},analysisFilter:{period:'6m',accountId:'',categoryId:'',merchant:''},modal:null,locked:false};

async function boot(){await db.open();await seed();await load();state.locked=!!(state.settings.pinEnabled&&state.settings.pinHash);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});document.addEventListener('visibilitychange',handleVisibilityLock);render()}
async function seed(){if(!(await db.all('accounts')).length)for(const a of DEFAULT_ACCOUNTS)await db.put('accounts',a);if(!(await db.all('categories')).length)for(const c of [...DEFAULT_CATEGORIES,...INCOME_CATEGORIES])await db.put('categories',c);if(!(await db.all('settings')).length)await db.put('settings',{id:'prefs',...state.settings});}
async function load(){state.tx=await db.all('transactions');state.accounts=await db.all('accounts');state.categories=await db.all('categories');state.tags=await db.all('tags');state.plans=await db.all('plans');state.rules=await db.all('rules');const s=(await db.all('settings')).find(x=>x.id==='prefs');if(s)state.settings={...state.settings,...s}}

function monthBounds(){const y=state.date.getFullYear(),m=state.date.getMonth();const k=`${y}-${String(m+1).padStart(2,'0')}`;return {y,m,k}}
function txForMonth(k=monthBounds().k){return state.tx.filter(t=>monthKey(t.date)===k)}
function cat(id){return state.categories.find(c=>c.id===id)}function acct(id){return state.accounts.find(a=>a.id===id)}
function realExpenses(list){return list.filter(t=>t.type==='expense'&&!t.parentRefundId).reduce((s,t)=>s+t.amount,0)}
function refunds(list){return list.filter(t=>t.type==='refund').reduce((s,t)=>s+t.amount,0)}
function incomes(list){return list.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0)}
function planFor(k){const own=state.plans.find(p=>p.id===k);if(own)return own;const d=state.settings.defaultPlan;if(d&&k>=d.from)return{id:k,expectedIncome:d.expectedIncome||0,savingsGoal:d.savingsGoal||0,explicitBudget:d.explicitBudget??null,categoryBudgets:d.categoryBudgets||{}};return{id:k,expectedIncome:0,savingsGoal:0,explicitBudget:null,categoryBudgets:{}}}
function expenseAllocations(t){if(t.type!=='expense')return[];if(Array.isArray(t.splits)&&t.splits.length)return t.splits.map(x=>({categoryId:x.categoryId,amount:Number(x.amount)||0}));return [{categoryId:t.categoryId,amount:t.amount}]}
function categoryTotals(list){const out={};for(const t of list){if(t.type==='expense')for(const x of expenseAllocations(t))out[x.categoryId]=(out[x.categoryId]||0)+x.amount;if(t.type==='refund'){const p=state.tx.find(x=>x.id===t.refundOf);if(p){const alloc=expenseAllocations(p),total=alloc.reduce((a,x)=>a+x.amount,0)||p.amount;for(const x of alloc)out[x.categoryId]=(out[x.categoryId]||0)-t.amount*(x.amount/total)}}}return out}
function calcTxSearchText(t){return [t.description,t.merchant,t.subcategory,t.note,(cat(t.categoryId)||{}).name,(acct(t.accountId)||{}).name,acct(t.fromAccountId)?.name,acct(t.toAccountId)?.name,(t.tags||[]).join(' ')].filter(Boolean).join(' ').toLowerCase()}
function hashText(str){if(crypto.subtle)return crypto.subtle.digest('SHA-256',new TextEncoder().encode(str)).then(buf=>[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join(''));return Promise.resolve('fallback-'+btoa(str))}
function renderLock(){return `<div class="lock-screen"><div class="lock-card card"><div class="lock-flower">🌸</div><h1>Finanças Pastel</h1><p>Introduz o teu PIN para continuar.</p><form id="unlock-form" class="form-grid"><input class="input pin-input" name="pin" inputmode="numeric" type="password" maxlength="8" autocomplete="off" placeholder="PIN" autofocus required><button class="save-btn" type="submit">Desbloquear</button></form></div></div>`}
function analysisStartDate(period){const now=new Date(),d=new Date(now);if(period==='1m')d.setMonth(d.getMonth()-1);else if(period==='3m')d.setMonth(d.getMonth()-3);else if(period==='6m')d.setMonth(d.getMonth()-6);else if(period==='1y')d.setFullYear(d.getFullYear()-1);else return null;return d.toISOString().slice(0,10)}
function filteredAnalysisTx(){let rows=[...state.tx];const f=state.analysisFilter,start=analysisStartDate(f.period);if(start)rows=rows.filter(t=>t.date>=start);if(f.accountId)rows=rows.filter(t=>t.accountId===f.accountId||t.fromAccountId===f.accountId||t.toAccountId===f.accountId);if(f.categoryId)rows=rows.filter(t=>t.categoryId===f.categoryId||(t.splits||[]).some(x=>x.categoryId===f.categoryId)||(t.type==='refund'&&state.tx.find(x=>x.id===t.refundOf)?.categoryId===f.categoryId));if(f.merchant)rows=rows.filter(t=>(t.merchant||'').toLowerCase().includes(f.merchant.toLowerCase())||(t.description||'').toLowerCase().includes(f.merchant.toLowerCase()));return rows}
function addMonths(dateStr,n=1){const d=new Date(dateStr+'T12:00:00');d.setMonth(d.getMonth()+n);return d.toISOString().slice(0,10)}
function upcomingItemsForMonth(k){return state.tx.filter(t=>t.recurring?.enabled&&t.type==='expense').map(t=>({t,date:recurringDateForMonth(t,k)})).filter(x=>x.date&&!state.tx.some(z=>z.generatedFrom===x.t.id&&z.date===x.date))}
function upcomingTotal(k=monthBounds().k){return upcomingItemsForMonth(k).reduce((s,x)=>s+x.t.amount,0)}
function analysisPeriodMonths(p){return p==='1m'?1:p==='3m'?3:p==='6m'?6:p==='1y'?12:null}
function comparisonAnalysisRows(){const n=analysisPeriodMonths(state.analysisFilter.period);if(!n)return[];const now=new Date(),curStart=new Date(now.getFullYear(),now.getMonth()-n+1,1),prevStart=new Date(curStart.getFullYear(),curStart.getMonth()-n,1),prevEnd=new Date(curStart);prevEnd.setDate(0);const start=prevStart.toISOString().slice(0,10),end=prevEnd.toISOString().slice(0,10),f=state.analysisFilter;return state.tx.filter(t=>t.date>=start&&t.date<=end).filter(t=>!f.accountId||t.accountId===f.accountId||t.fromAccountId===f.accountId||t.toAccountId===f.accountId).filter(t=>!f.categoryId||t.categoryId===f.categoryId||(t.splits||[]).some(x=>x.categoryId===f.categoryId)).filter(t=>!f.merchant||(t.merchant||t.description||'').toLowerCase().includes(f.merchant.toLowerCase()))}
function activeRuleFor(text){const q=(text||'').toLowerCase();return state.rules.find(r=>r.enabled!==false&&q.includes((r.match||'').toLowerCase()))}
function monthStats(k=monthBounds().k){const list=txForMonth(k),inc=incomes(list),gross=realExpenses(list),ref=refunds(list),exp=gross-ref,p=planFor(k);const expected=p.expectedIncome||inc;const budget=p.explicitBudget ?? Math.max(0,expected-(p.savingsGoal||0));const remaining=budget-exp;return{list,inc,gross,ref,exp,p,expected,budget,remaining,savings:inc-exp}}
function accountAccumulated(id){let v=0;for(const t of state.tx){if(t.type==='income'&&t.accountId===id)v+=t.amount;if(t.type==='expense'&&t.accountId===id)v-=t.amount;if(t.type==='refund'&&t.accountId===id)v+=t.amount;if(t.type==='transfer'){if(t.fromAccountId===id)v-=t.amount;if(t.toAccountId===id)v+=t.amount}}return v}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function money(v){return state.settings.hideValues?'••••':currencyFmt.format(v||0)}
function toast(msg){const e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}

function shell(content,title=''){return `<main class="app-shell"><div class="topbar">${title?`<h1>${title}</h1>`:'<span></span>'}<span></span></div>${content}</main>${nav()}`}
function nav(){const items=[['month','▣','Mês'],['movements','⇆','Movimentos'],['add','＋',''],['analysis','◔','Análise'],['more','☰','Mais']];return `<nav class="bottom-nav">${items.map(([id,ic,l])=>id==='add'?`<button class="fab" data-action="open-add">+</button>`:`<button class="nav-btn ${state.tab===id?'active':''}" data-tab="${id}"><span class="nav-icon">${ic}</span><span>${l}</span></button>`).join('')}</nav>`}

function render(){if(state.locked){document.getElementById('app').innerHTML=renderLock();bind();return}let html='';if(state.tab==='month')html=renderMonth();if(state.tab==='movements')html=renderMovements();if(state.tab==='analysis')html=renderAnalysis();if(state.tab==='more')html=renderMore();document.getElementById('app').innerHTML=html+(state.modal?renderModal():'');bind()}

function renderMonth(){const {y,m,k}=monthBounds(),s=monthStats(k),now=new Date(),monthStart=new Date(y,m,1),currentStart=new Date(now.getFullYear(),now.getMonth(),1),isPast=(new Date(y,m+1,0)<currentStart),isFuture=(monthStart>currentStart),pct=s.budget?Math.round(s.exp/s.budget*100):0;const daysLeft=isFuture?null:Math.max(1,new Date(y,m+1,0).getDate()-now.getDate()+1);const daily=daysLeft? s.remaining/daysLeft:null;const byCat=categoryTotals(s.list);const cats=Object.entries(byCat).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]);const prev=new Date(y,m-1,1),prevS=monthStats(`${prev.getFullYear()}-${String(prev.getMonth()+1).padStart(2,'0')}`);const diff=prevS.exp?((s.exp-prevS.exp)/prevS.exp*100):null;return `<main class="app-shell">
<div class="topbar"><button class="icon-btn" data-action="prev-month">‹</button><button class="month-title" data-action="pick-month">${monthName(y,m)}</button><button class="icon-btn" data-action="next-month">›</button></div>
${isPast?monthlySummary(s,diff):isFuture?futureHero(s):currentHero(s,pct,daily,k)}
<div class="hero-grid">${metric('Receitas',money(s.inc),'mint')}${metric('Despesas',money(s.exp),'pink')}${metric('Poupança atual',money(s.savings),'lilac')}${metric('Previsto ainda sair',money(upcomingTotal(k)),'peach')}</div>
${!isPast?insights(s,pct):''}
<section class="section"><div class="section-title"><h2>Despesas por categoria</h2></div><div class="card category-list">${cats.length?cats.map(([id,v])=>categoryRow(id,v,s.exp)).join(''):'<div class="empty">Ainda não há despesas neste mês.</div>'}</div></section>
<section class="section"><div class="section-title"><h2>Gastos ao longo do mês</h2></div><div class="card chart-card">${lineChart(s.list,s.budget,y,m)}</div></section>
${upcomingSection(k)}
<section class="section"><div class="section-title"><h2>Recentes</h2><button class="text-btn" data-action="go-month-movements">Ver todos</button></div><div class="card txn-list">${recentRows(s.list)}</div></section>
</main>${nav()}`}
function futureHero(s){return `<section class="card hero"><div class="eyebrow">Planeamento do mês 🌸</div><div class="hero-value">${s.budget?money(s.budget):'Define o teu plano mensal'}</div><div class="hero-sub">${s.budget?`limite de despesas para poupares ${money(s.p.savingsGoal||0)}`:'Receita prevista + objetivo de poupança'}</div>${s.budget?'':`<button class="secondary-btn" style="margin-top:14px" data-action="edit-plan">Definir objetivo</button>`}</section>`}
function currentHero(s,pct,daily,k){let cls=pct>=100?'danger':pct>=85?'warn':'',pred=upcomingTotal(k),after=s.remaining-pred,title=s.budget?`${money(Math.max(0,s.remaining))} disponíveis`:'Define o teu plano mensal';return `<section class="card hero ${cls}"><div class="eyebrow">${pct<75?'Estás no bom caminho 🌸':pct<100?'Atenção aos gastos':'Objetivo comprometido'}</div><div class="hero-value">${title}</div><div class="hero-sub">${s.budget?'para manteres o objetivo de poupança':'Receita prevista + objetivo de poupança'}</div>${s.budget?`<div class="progress"><span style="width:${Math.min(100,pct)}%"></span></div><div class="tiny">Gastaste ${money(s.exp)} de ${money(s.budget)} · ${pct}%</div><div class="row-sub" style="margin-top:14px">🎯 Objetivo de poupança ${money(s.p.savingsGoal||0)} · ${money(Math.max(0,daily))}/dia disponíveis</div>${pred?`<div class="forecast-strip">Após ${money(pred)} previstos, ficam <b>${money(after)}</b></div>`:''}`:`<button class="secondary-btn" style="margin-top:14px" data-action="edit-plan">Definir objetivo</button>`}</section>`}
function monthlySummary(s,diff){return `<section class="card hero" style="background:linear-gradient(145deg,var(--pink),#fff 78%)"><div class="eyebrow">🌸 Resumo do mês</div><div class="hero-value">Poupaste ${money(s.savings)}</div><div class="hero-sub">Objetivo: ${money(s.p.savingsGoal||0)} ${s.p.savingsGoal?`· ${s.savings>=s.p.savingsGoal?'✓ acima do objetivo':'abaixo do objetivo'}`:''}</div>${diff!==null?`<div class="row-sub" style="margin-top:12px">${diff<0?'↓':'↑'} ${Math.abs(diff).toFixed(0)}% de despesas vs mês anterior</div>`:''}<button class="secondary-btn" style="margin-top:14px" data-action="open-summary">Ver resumo completo →</button></section>`}
function metric(label,val,cls){return `<div class="metric ${cls}"><small>${label}</small><b>${val}</b></div>`}
function insights(s,pct){const arr=[];const budgetAlert=s.budget&&((pct>=100&&state.settings.alertOver)||(pct>=90&&pct<100&&state.settings.alert90)||(pct>=75&&pct<90&&state.settings.alert75));if(budgetAlert)arr.push(['⚠️',pct>=100?'Ultrapassaste o limite':'Estás perto do limite',`${pct}% do orçamento mensal utilizado.`,'peach']);const now=new Date(),{y,m}=monthBounds(),isCurrent=y===now.getFullYear()&&m===now.getMonth();if(isCurrent&&s.budget&&now.getDate()>2){const days=new Date(y,m+1,0).getDate(),forecastExp=s.exp/now.getDate()*days,forecastSavings=s.expected-forecastExp;if(s.p.savingsGoal&&forecastSavings<s.p.savingsGoal)arr.push(['🎯','Objetivo de poupança em risco',`Ao ritmo atual, a previsão é poupares ${money(forecastSavings)} (${money(s.p.savingsGoal-forecastSavings)} abaixo do objetivo).`,'pink'])}const catTotals=categoryTotals(s.list);for(const [id,limit] of Object.entries(s.p.categoryBudgets||{})){const v=catTotals[id]||0;if(limit&&v/limit>=.9){const c=cat(id);arr.push([c?.emoji||'•',`${c?.name||'Categoria'} perto do limite`,`${money(v)} de ${money(limit)} utilizados.`,'peach']);break}}const rev=state.accounts.find(a=>a.name.toLowerCase().includes('revolut'));if(rev?.monthlyGoal){const grossSpent=s.list.filter(t=>t.type==='expense'&&t.accountId===rev.id).reduce((x,t)=>x+t.amount,0),creditedRefunds=s.list.filter(t=>t.type==='refund'&&t.accountId===rev.id).reduce((x,t)=>x+t.amount,0),spent=grossSpent-creditedRefunds;arr.push(['💳','Revolut',`Gastaste ${money(spent)} de ${money(rev.monthlyGoal)} neste mês.`,'lilac'])}if(!arr.length)return'';return `<section class="section"><div class="section-title"><h2>Insights</h2></div>${arr.slice(0,2).map(x=>`<div class="card insight"><span class="bubble ${x[3]}">${x[0]}</span><div><b>${x[1]}</b><p>${x[2]}</p></div></div>`).join('')}</section>`}
function categoryRow(id,v,total){const c=cat(id)||{name:'Sem categoria',emoji:'•',color:'#eee'},p=planFor(monthBounds().k),limit=p.categoryBudgets?.[id],pct=limit?Math.round(v/limit*100):(total?Math.round(v/total*100):0),expanded=state.expandedCat===id,tx=txForMonth().filter(t=>t.type==='expense'&&(t.categoryId===id||(t.splits||[]).some(x=>x.categoryId===id)));return `<div><button class="row" style="width:100%;border-left:0;border-right:0;border-top:0;background:transparent;text-align:left" data-action="toggle-cat" data-id="${id}"><span class="cat-icon" style="background:${c.color}">${c.emoji}</span><span class="row-main"><span class="row-title">${esc(c.name)}</span><span class="row-sub">${tx.length} movimentos · ${limit?`${money(v)} de ${money(limit)}`:`${pct}%`}</span><span class="bar"><span style="width:${Math.min(100,pct)}%"></span></span></span><span class="row-amount">${money(v)}<br><span class="row-sub">${expanded?'⌃':'⌄'}</span></span></button>${expanded?`<div class="cat-detail">${tx.map(t=>{const alloc=t.splits?.find(x=>x.categoryId===id)?.amount??t.amount;return `<div class="mini-txn"><span>${esc(t.description)}<small class="row-sub"> · ${fmtDate(t.date)}</small></span><b>${money(alloc)}</b></div>`}).join('')}</div>`:''}</div>`}
function lineChart(list,budget,y,m){const days=new Date(y,m+1,0).getDate(), daily=Array(days).fill(0);for(const t of list){if(t.type==='expense')daily[Number(t.date.slice(8,10))-1]+=t.amount;if(t.type==='refund')daily[Number(t.date.slice(8,10))-1]-=t.amount}let acc=0,pts=[];daily.forEach((v,i)=>{acc+=v;pts.push(acc)});const max=Math.max(budget||0,...pts,1),w=520,h=150,pad=10;const path=pts.map((v,i)=>`${i?'L':'M'} ${pad+i*(w-2*pad)/(days-1)} ${h-pad-v/max*(h-2*pad)}`).join(' ');const ideal=budget?`M ${pad} ${h-pad} L ${w-pad} ${pad}`:'';return `<div class="legend"><span>━ Gasto acumulado</span><span>┄ Ritmo para o objetivo</span></div><svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path d="${ideal}" fill="none" stroke="#aaa2ad" stroke-dasharray="6 6" stroke-width="2"/><path d="${path}" fill="none" stroke="#b9a7d5" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function recurringDateForMonth(t,k){if(!t.recurring?.enabled||!t.recurring.nextDate)return null;const [ty,tm]=k.split('-').map(Number),start=new Date(t.recurring.nextDate+'T12:00:00'),targetIndex=ty*12+(tm-1),startIndex=start.getFullYear()*12+start.getMonth();if(targetIndex<startIndex)return null;if((t.recurring.frequency||'mensal')!=='mensal'&&targetIndex!==startIndex)return null;const last=new Date(ty,tm,0).getDate(),day=Math.min(start.getDate(),last);return `${ty}-${String(tm).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function upcomingSection(k){const items=state.tx.filter(t=>t.recurring?.enabled&&t.type==='expense').map(t=>({t,date:recurringDateForMonth(t,k)})).filter(x=>x.date&&!state.tx.some(z=>z.generatedFrom===x.t.id&&z.date===x.date)).sort((a,b)=>a.date.localeCompare(b.date));if(!items.length)return'';const rows=items.slice(0,6).map(({t,date})=>`<div class="row"><span class="cat-icon" style="background:var(--butter)">🔁</span><span class="row-main"><span class="row-title">${esc(t.description)}</span><span class="row-sub">${fmtDate(date)} · previsto</span></span><span class="row-amount">${money(t.amount)}</span><button class="mini-action" data-action="confirm-recurring" data-id="${t.id}" data-date="${date}">Confirmar</button></div>`).join('');return `<section class="section"><div class="section-title"><h2>Próximos</h2></div><div class="card txn-list">${rows}</div></section>`}
function recentRows(list){const rows=[...list].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);return rows.length?rows.map(txRow).join(''):'<div class="empty">Ainda não há movimentos.</div>'}

function renderMovements(){let rows=[...state.tx].sort((a,b)=>b.date.localeCompare(a.date));const q=state.search.toLowerCase().trim();if(q)rows=rows.filter(t=>calcTxSearchText(t).includes(q));if(state.filter!=='all')rows=rows.filter(t=>t.type===state.filter);const f=state.advFilter||{};if(f.start)rows=rows.filter(t=>t.date>=f.start);if(f.end)rows=rows.filter(t=>t.date<=f.end);if(f.categoryId)rows=rows.filter(t=>t.categoryId===f.categoryId||(t.splits||[]).some(x=>x.categoryId===f.categoryId));if(f.accountId)rows=rows.filter(t=>t.accountId===f.accountId||t.fromAccountId===f.accountId||t.toAccountId===f.accountId);if(f.min)rows=rows.filter(t=>t.amount>=Number(f.min));if(f.max)rows=rows.filter(t=>t.amount<=Number(f.max));if(f.recurring==='yes')rows=rows.filter(t=>t.recurring?.enabled);if(f.recurring==='no')rows=rows.filter(t=>!t.recurring?.enabled);if(f.tag)rows=rows.filter(t=>(t.tags||[]).some(x=>x.toLowerCase().includes(f.tag.toLowerCase())));const groups={};for(const t of rows)(groups[t.date]??=[]).push(t);const active=Object.values(f).some(Boolean);return shell(`<div class="searchbar"><input id="search" class="input" placeholder="Pesquisar movimentos" value="${esc(state.search)}"><button class="filter-btn ${active?'active':''}" data-action="advanced-filters">⚙︎</button></div><div class="chips">${[['all','Todos'],['expense','Despesas'],['income','Receitas'],['refund','Reembolsos'],['transfer','Transferências']].map(([id,l])=>`<button class="chip ${state.filter===id?'active':''}" data-filter="${id}">${l}</button>`).join('')}</div>${active?`<div class="filter-summary">Filtros avançados ativos <button class="text-btn" data-action="clear-filters">Limpar</button></div>`:''}${Object.entries(groups).map(([d,txs])=>`<div class="group-label">${fmtDate(d)}</div><div class="card txn-list">${txs.map(txRow).join('')}</div>`).join('')||'<div class="empty">Sem resultados.</div>'}`,'Movimentos')}
function txRow(t){let label=t.description,sub='';if(t.type==='transfer'){sub=`${acct(t.fromAccountId)?.name||'?'} → ${acct(t.toAccountId)?.name||'?'}`;return `<button class="row" style="width:100%;background:transparent;border-left:0;border-right:0;border-top:0;text-align:left" data-action="tx-detail" data-id="${t.id}"><span class="cat-icon blue">↔</span><span class="row-main"><span class="row-title">${esc(label)}</span><span class="row-sub">${esc(sub)}</span></span><span class="row-amount">${money(t.amount)}</span></button>`}const c=cat(t.categoryId),a=acct(t.accountId);sub=`${c?.name||t.type} · ${a?.name||''}`;const sign=t.type==='expense'?'-':'+';return `<button class="row" style="width:100%;background:transparent;border-left:0;border-right:0;border-top:0;text-align:left" data-action="tx-detail" data-id="${t.id}"><span class="cat-icon" style="background:${c?.color||'#eee'}">${t.type==='refund'?'↩':c?.emoji||'•'}</span><span class="row-main"><span class="row-title">${esc(label)}</span><span class="row-sub">${esc(sub)}</span></span><span class="row-amount ${t.type==='expense'?'negative':'positive'}">${sign}${money(t.amount)}</span></button>`}

function renderAnalysis(){const rows=filteredAnalysisTx(),prevRows=comparisonAnalysisRows(),all=rows.filter(t=>t.type==='expense'||t.type==='refund'),inc=incomes(rows),exp=realExpenses(rows)-refunds(rows),prevExp=realExpenses(prevRows)-refunds(prevRows),delta=prevExp?((exp-prevExp)/prevExp*100):null;const weekdays=Array(7).fill(0);for(const t of all){let v=t.type==='refund'?-t.amount:t.amount;weekdays[new Date(t.date+'T12:00:00').getDay()]+=v}const order=[1,2,3,4,5,6,0],vals=order.map(i=>Math.max(0,weekdays[i])),max=Math.max(...vals,1),labels=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];const weekend=weekdays[0]+weekdays[6],weekday=weekdays.reduce((s,v,i)=>s+(i===0||i===6?0:v),0),tot=weekend+weekday||1;const cats=categoryTotals(all),prevCats=categoryTotals(prevRows.filter(t=>t.type==='expense'||t.type==='refund')),top=Object.entries(cats).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]).slice(0,8),changes=Object.entries(cats).map(([id,v])=>({id,v,d:v-(prevCats[id]||0)})).sort((a,b)=>Math.abs(b.d)-Math.abs(a.d)).slice(0,4);const merchants={};for(const t of all.filter(x=>x.type==='expense')){const n=t.merchant||t.description;if(n)merchants[n]=(merchants[n]||0)+t.amount}const tops=Object.entries(merchants).sort((a,b)=>b[1]-a[1]).slice(0,5);return shell(`<div class="analysis-filters"><select id="analysis-period" class="select"><option value="1m" ${state.analysisFilter.period==='1m'?'selected':''}>1 mês</option><option value="3m" ${state.analysisFilter.period==='3m'?'selected':''}>3 meses</option><option value="6m" ${state.analysisFilter.period==='6m'?'selected':''}>6 meses</option><option value="1y" ${state.analysisFilter.period==='1y'?'selected':''}>1 ano</option><option value="all" ${state.analysisFilter.period==='all'?'selected':''}>Tudo</option></select><select id="analysis-account" class="select"><option value="">Todas as contas</option>${state.accounts.map(a=>`<option value="${a.id}" ${state.analysisFilter.accountId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select><select id="analysis-category" class="select"><option value="">Todas as categorias</option>${state.categories.filter(c=>c.type==='expense'&&!c.archived).map(c=>`<option value="${c.id}" ${state.analysisFilter.categoryId===c.id?'selected':''}>${c.emoji} ${esc(c.name)}</option>`).join('')}</select><input id="analysis-merchant" class="input" placeholder="Loja/empresa" value="${esc(state.analysisFilter.merchant)}"></div><section class="section"><div class="analysis-grid">${metric('Receitas',money(inc),'mint')}${metric('Despesas',money(exp),'pink')}${metric('Poupança',money(inc-exp),'lilac')}${metric('Movimentos',String(rows.length),'blue')}</div></section>${delta!==null?`<section class="section"><div class="card comparison-card"><div><small>Comparação com período anterior</small><b class="${delta<=0?'positive':'negative'}">${delta>=0?'+':''}${delta.toFixed(1)}%</b><span>${money(exp-prevExp)} de diferença em despesas</span></div></div></section>`:''}<section class="section"><div class="section-title"><h2>O que mais mudou</h2></div><div class="card">${changes.map(x=>`<div class="row"><span class="cat-icon" style="background:${cat(x.id)?.color||'#eee'}">${cat(x.id)?.emoji||'•'}</span><span class="row-main row-title">${esc(cat(x.id)?.name||'Categoria')}</span><span class="row-amount ${x.d<=0?'positive':'negative'}">${x.d>=0?'+':''}${money(x.d)}</span></div>`).join('')||'<div class="empty">Sem comparação disponível.</div>'}</div></section><section class="section"><div class="section-title"><h2>Gastos por dia da semana</h2></div><div class="card chart-card"><div class="weekday">${vals.map((v,i)=>`<div class="daybar"><i style="height:${Math.max(8,v/max*130)}px"></i>${labels[i]}<div class="tiny">${money(v)}</div></div>`).join('')}</div></div></section><section class="section"><div class="section-title"><h2>Dias úteis vs fim de semana</h2></div><div class="analysis-grid"><div class="card stat mint"><small>Dias úteis</small><b>${Math.round(weekday/tot*100)}%</b><div class="tiny">${money(weekday)}</div></div><div class="card stat lilac"><small>Fim de semana</small><b>${Math.round(weekend/tot*100)}%</b><div class="tiny">${money(weekend)}</div></div></div></section><section class="section"><div class="section-title"><h2>Top categorias</h2></div><div class="card category-list">${top.map(([id,v])=>categoryRowSimple(id,v)).join('')||'<div class="empty">Ainda não há dados.</div>'}</div></section><section class="section"><div class="section-title"><h2>Onde gastaste mais</h2></div><div class="card category-list">${tops.map(([n,v])=>`<div class="row"><span class="cat-icon" style="background:var(--peach)">⌂</span><span class="row-main row-title">${esc(n)}</span><span class="row-amount">${money(v)}</span></div>`).join('')||'<div class="empty">Sem dados suficientes.</div>'}</div></section>`,'Análise')}
function categoryRowSimple(id,v){const c=cat(id)||{};return `<div class="row"><span class="cat-icon" style="background:${c.color||'#eee'}">${c.emoji||'•'}</span><span class="row-main"><span class="row-title">${esc(c.name||'Sem categoria')}</span></span><span class="row-amount">${money(v)}</span></div>`}

function renderMore(){return shell(`<section><div class="section-title"><h2>As minhas contas</h2><button class="text-btn" data-action="new-account">＋ Adicionar</button></div>${state.accounts.map(a=>`<button class="card account-card" style="width:100%;text-align:left;border:0" data-action="account-detail" data-id="${a.id}"><div class="account-head"><div><h3>${a.emoji} ${esc(a.name)}</h3><div class="tiny">Acumulado desde €0</div></div><div class="account-balance">${money(accountAccumulated(a.id))}</div></div>${a.monthlyGoal?`<div class="tiny" style="margin-top:10px">Objetivo mensal: ${money(a.monthlyGoal)}</div>`:''}</button>`).join('')}</section><section class="section"><div class="card menu-list">${menuRow('🗂️','Categorias e tags','categories')}${menuRow('⚡','Regras automáticas','rules')}${menuRow('🎯','Orçamento e objetivos','plan')}${menuRow('⚙️','Definições','settings')}${menuRow('💾','Backups e exportação','backup')}</div></section>`,'Mais')}
function menuRow(ic,l,act){return `<button class="row" style="width:100%;background:transparent;border-left:0;border-right:0;border-top:0;text-align:left" data-action="${act}"><span>${ic}</span><span class="row-main row-title">${l}</span><span>›</span></button>`}

function renderModal(){const m=state.modal;if(m.type==='add')return addModal(m.kind||'expense');if(m.type==='edit')return editTxModal(m.id);if(m.type==='tx')return txModal(m.id);if(m.type==='refund')return refundModal(m.id);if(m.type==='split')return splitModal(m.id);if(m.type==='plan')return planModal();if(m.type==='settings')return settingsModal();if(m.type==='backup')return backupModal();if(m.type==='account')return accountModal(m.id);if(m.type==='account-edit')return accountEditModal(m.id);if(m.type==='categories')return categoriesModal();if(m.type==='category-edit')return categoryEditModal(m.id,m.kind);if(m.type==='filters')return filtersModal();if(m.type==='rules')return rulesModal();if(m.type==='rule-edit')return ruleEditModal(m.id,m.sourceTxId);if(m.type==='summary')return summaryModal(m.k);if(m.type==='pin-setup')return pinSetupModal();return''}
function modalFrame(title,body){return `<div class="modal-wrap" data-action="close-modal"><div class="modal" onclick="event.stopPropagation()"><div class="modal-head"><button class="icon-btn" data-action="close-modal">×</button><h2>${title}</h2><span style="width:38px"></span></div>${body}</div></div>`}
function addModal(kind){const cats=state.categories.filter(c=>c.type===(kind==='income'?'income':'expense')&&!c.archived),todayD=today();return modalFrame('Novo movimento',`<div class="segment">${[['expense','Despesa'],['income','Receita'],['transfer','Transferência']].map(([k,l])=>`<button class="seg-btn ${kind===k?'active':''}" data-kind="${k}" data-action="switch-kind">${l}</button>`).join('')}</div><form id="tx-form" class="form-grid">${kind==='transfer'?transferFields(todayD):normalFields(kind,cats,todayD)}<button type="submit" class="save-btn">Guardar</button><button type="submit" class="secondary-btn" data-save-another="1">Guardar e adicionar outro</button></form>`)}
function normalFields(kind,cats,date){return `<input type="hidden" name="kind" value="${kind}"><div class="field"><label>Valor</label><input class="input" name="amount" inputmode="decimal" placeholder="0,00" required autofocus></div><div class="field"><label>Descrição</label><input class="input" name="description" placeholder="Ex.: Zara - calças pretas" required></div><div class="inline-grid"><div class="field"><label>Categoria</label><select class="select" name="categoryId" required><option value="">Escolher</option>${cats.map(c=>`<option value="${c.id}">${c.emoji} ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Conta</label><select class="select" name="accountId" required>${state.accounts.map(a=>`<option value="${a.id}">${a.emoji} ${esc(a.name)}</option>`).join('')}</select></div></div><div class="field"><label>Data</label><input class="input" type="date" name="date" value="${date}" required></div><button type="button" class="more-toggle text-btn" data-action="toggle-more">＋ Mais opções</button><div id="more-fields" class="form-grid hidden"><div class="field"><label>Loja / Empresa</label><input class="input" name="merchant" placeholder="Ex.: Zara, Fidelidade, Audi"></div><div class="field"><label>Subcategoria</label><input class="input" name="subcategory" placeholder="Opcional"></div><div class="field"><label>Tags</label><input class="input" name="tags" placeholder="Ex.: Japão2027, Natal"></div><div class="field"><label>Nota</label><textarea name="note" rows="2" placeholder="Opcional"></textarea></div>${kind==='expense'?`<label class="toggle-row card"><span>🔁 Repetir este movimento</span><input class="switch" type="checkbox" name="recurring"></label><div class="inline-grid"><div class="field"><label>Frequência</label><select class="select" name="recurringFrequency"><option value="mensal">Mensal</option></select></div><div class="field"><label>Próxima data</label><input class="input" type="date" name="recurringNextDate"></div></div>`:''}</div>`}
function transferFields(date){return `<input type="hidden" name="kind" value="transfer"><div class="field"><label>Valor</label><input class="input" name="amount" inputmode="decimal" required autofocus></div><div class="field"><label>Descrição</label><input class="input" name="description" value="Transferência" required></div><div class="inline-grid"><div class="field"><label>De</label><select class="select" name="fromAccountId" required>${state.accounts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>Para</label><select class="select" name="toAccountId" required>${state.accounts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div></div><div class="field"><label>Data</label><input class="input" type="date" name="date" value="${date}" required></div>`}
function txModal(id){const t=state.tx.find(x=>x.id===id);if(!t)return'';const canRefund=t.type==='expense',refTotal=state.tx.filter(x=>x.type==='refund'&&x.refundOf===id).reduce((s,x)=>s+x.amount,0);return modalFrame('Movimento',`<div class="card" style="padding:18px"><div class="hero-value" style="font-size:28px">${t.type==='expense'?'-':t.type==='transfer'?'': '+'}${money(t.amount)}</div><div class="row-title">${esc(t.description)}</div><div class="row-sub">${fmtDate(t.date)}</div>${t.merchant?`<div class="row-sub">Loja/Empresa: ${esc(t.merchant)}</div>`:''}${t.tags?.length?`<div class="chips" style="margin-top:10px">${t.tags.map(x=>`<span class="chip active">#${esc(x)}</span>`).join('')}</div>`:''}${t.splits?.length?`<div class="row-sub" style="margin-top:10px">Dividida por ${t.splits.length} categorias</div>`:''}${refTotal?`<div class="row-sub" style="margin-top:6px">Reembolsado: ${money(refTotal)}</div>`:''}${t.note?`<p>${esc(t.note)}</p>`:''}</div><div class="form-grid" style="margin-top:14px"><button class="secondary-btn" data-action="edit-tx" data-id="${t.id}">✎ Editar movimento</button>${canRefund&&refTotal<t.amount?`<button class="secondary-btn" data-action="refund" data-id="${t.id}">↩ Registar reembolso</button>`:''}${canRefund?`<button class="secondary-btn" data-action="split" data-id="${t.id}">✂ Dividir por categorias</button>`:''}${canRefund?`<button class="secondary-btn" data-action="new-rule-from-tx" data-id="${t.id}">⚡ Criar regra a partir deste movimento</button>`:''}<button class="secondary-btn danger-btn" data-action="delete-tx" data-id="${t.id}">Apagar movimento</button></div>`)}
function refundModal(id){const t=state.tx.find(x=>x.id===id);state.modal={type:'refund',id};return modalFrame('Reembolso',`<div class="card row"><span class="cat-icon">↩</span><span class="row-main"><span class="row-title">${esc(t.description)}</span><span class="row-sub">Compra original · ${money(t.amount)}</span></span></div><form id="refund-form" class="form-grid" style="margin-top:14px"><input type="hidden" name="refundOf" value="${id}"><div class="field"><label>Valor devolvido</label><input class="input" name="amount" inputmode="decimal" max="${t.amount}" required></div><div class="field"><label>Data</label><input class="input" type="date" name="date" value="${today()}" required></div><div class="field"><label>Conta</label><select class="select" name="accountId">${state.accounts.map(a=>`<option value="${a.id}" ${a.id===t.accountId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>Nota</label><input class="input" name="note" placeholder="Opcional"></div><button class="save-btn" type="submit">Guardar reembolso</button></form>`)}
function planModal(){const {k}=monthBounds(),p=planFor(k),expenseCats=state.categories.filter(c=>c.type==='expense'&&!c.archived);return modalFrame(`Plano de ${monthName(state.date.getFullYear(),state.date.getMonth())}`,`<form id="plan-form" class="form-grid"><div class="field"><label>Receita prevista</label><input class="input" name="expectedIncome" inputmode="decimal" value="${p.expectedIncome||''}"></div><div class="field"><label>Objetivo de poupança</label><input class="input" name="savingsGoal" inputmode="decimal" value="${p.savingsGoal||''}"></div><div class="field"><label>Limite de despesas explícito (opcional)</label><input class="input" name="explicitBudget" inputmode="decimal" value="${p.explicitBudget??''}" placeholder="Se vazio: receita − poupança"></div><div class="note">O objetivo pode ser diferente em cada mês. Se não definires limite explícito, o orçamento é calculado automaticamente.</div><label class="toggle-row card"><span>Usar estes valores como habitual a partir deste mês</span><input class="switch" type="checkbox" name="applyFuture" ${state.settings.defaultPlan&&state.settings.defaultPlan.from===k?'checked':''}></label><details class="card details-card"><summary>Orçamentos por categoria (opcional)</summary><div class="form-grid" style="margin-top:12px">${expenseCats.map(c=>`<div class="field"><label>${c.emoji} ${esc(c.name)}</label><input class="input category-budget-input" data-category-id="${c.id}" inputmode="decimal" value="${p.categoryBudgets?.[c.id]??''}" placeholder="Sem limite"></div>`).join('')}</div></details><button class="save-btn" type="submit">Guardar plano</button></form>`)}
function settingsModal(){return modalFrame('Definições',`<section class="settings-section"><div class="section-title"><h2>Privacidade</h2></div><div class="card"><label class="toggle-row"><span>Utilizar PIN <small class="row-sub">desligado por defeito</small></span><input id="pin-toggle" class="switch" type="checkbox" ${state.settings.pinEnabled?'checked':''}></label>${state.settings.pinEnabled?`<div class="field" style="padding:12px 16px"><label>Bloqueio automático</label><select id="auto-lock-select" class="select"><option value="0" ${!state.settings.autoLockMinutes?'selected':''}>Nunca</option><option value="1" ${state.settings.autoLockMinutes===1?'selected':''}>Após 1 minuto</option><option value="5" ${state.settings.autoLockMinutes===5?'selected':''}>Após 5 minutos</option><option value="15" ${state.settings.autoLockMinutes===15?'selected':''}>Após 15 minutos</option></select></div><button class="row" style="width:100%;border:0;background:transparent" data-action="change-pin"><span>🔐</span><span class="row-main row-title">Alterar PIN</span><span>›</span></button><button class="row" style="width:100%;border:0;background:transparent" data-action="lock-now"><span>🔒</span><span class="row-main row-title">Bloquear agora</span><span>›</span></button>`:''}<label class="toggle-row"><span>Ocultar valores</span><input id="hide-toggle" class="switch" type="checkbox" ${state.settings.hideValues?'checked':''}></label></div></section><section class="settings-section"><div class="section-title"><h2>Alertas</h2></div><div class="card"><label class="toggle-row"><span>Avisar aos 75%</span><input class="switch setting-toggle" data-key="alert75" type="checkbox" ${state.settings.alert75?'checked':''}></label><label class="toggle-row"><span>Avisar aos 90%</span><input class="switch setting-toggle" data-key="alert90" type="checkbox" ${state.settings.alert90?'checked':''}></label><label class="toggle-row"><span>Avisar ao ultrapassar</span><input class="switch setting-toggle" data-key="alertOver" type="checkbox" ${state.settings.alertOver?'checked':''}></label><label class="toggle-row"><span>Notificações do sistema</span><input id="notifications-toggle" class="switch" type="checkbox" ${state.settings.notificationsEnabled?'checked':''}></label></div></section><p class="note">As notificações locais funcionam quando a PWA está ativa. Alertas push em segundo plano exigem um serviço externo e não são simulados pela app.</p>`)}
function backupModal(){return modalFrame('Backups e exportação',`<div class="form-grid"><button class="secondary-btn" data-action="download-backup">💾 Criar backup completo</button><button class="secondary-btn" data-action="export-csv">📄 Exportar movimentos CSV</button><label class="secondary-btn" style="text-align:center">📥 Restaurar backup<input id="restore-file" type="file" accept="application/json" hidden></label><button class="secondary-btn danger-btn" data-action="wipe">Apagar todos os movimentos</button></div>`)}
function accountModal(id){const a=acct(id),acc=accountAccumulated(id),tx=state.tx.filter(t=>t.accountId===id||t.fromAccountId===id||t.toAccountId===id).sort((x,y)=>y.date.localeCompare(x.date));const {k}=monthBounds(),m=txForMonth(k),spent=m.filter(t=>t.type==='expense'&&t.accountId===id).reduce((s,t)=>s+t.amount,0)-m.filter(t=>t.type==='refund'&&t.accountId===id).reduce((s,t)=>s+t.amount,0),inT=m.filter(t=>t.type==='transfer'&&t.toAccountId===id).reduce((s,t)=>s+t.amount,0),outT=m.filter(t=>t.type==='transfer'&&t.fromAccountId===id).reduce((s,t)=>s+t.amount,0);const months=[];for(let i=5;i>=0;i--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const mk=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,ml=txForMonth(mk),sv=ml.filter(t=>t.type==='expense'&&t.accountId===id).reduce((q,t)=>q+t.amount,0)-ml.filter(t=>t.type==='refund'&&t.accountId===id).reduce((q,t)=>q+t.amount,0),tr=ml.filter(t=>t.type==='transfer'&&t.toAccountId===id).reduce((q,t)=>q+t.amount,0);months.push({label:new Intl.DateTimeFormat('pt-PT',{month:'short'}).format(d),spent:sv,transferred:tr})}const avg=months.reduce((s,x)=>s+x.spent,0)/months.length,within=a.monthlyGoal?months.filter(x=>x.spent<=a.monthlyGoal).length:0,max=Math.max(...months.map(x=>x.spent),a.monthlyGoal||0,1);return modalFrame(a.name,`<div class="card hero"><div class="eyebrow">Acumulado atual</div><div class="hero-value">${money(acc)}</div><div class="hero-sub">Calculado desde o ponto inicial €0</div></div><div class="hero-grid">${metric('Gasto este mês',money(spent),'pink')}${metric('Entradas por transferência',money(inT),'mint')}${metric('Saídas por transferência',money(outT),'peach')}${metric('Média 6 meses',money(avg),'lilac')}</div>${a.monthlyGoal?`<section class="section"><div class="card" style="padding:16px"><b>Objetivo mensal ${money(a.monthlyGoal)}</b><div class="progress"><span style="width:${Math.min(100,spent/a.monthlyGoal*100)}%"></span></div><div class="tiny">${money(spent)} gastos · ${within} de 6 meses dentro do objetivo</div><div class="mini-bars">${months.map(x=>`<div><i style="height:${Math.max(5,x.spent/max*72)}px"></i><small>${x.label}</small></div>`).join('')}</div></div></section>`:''}<button class="secondary-btn" style="width:100%;margin-top:14px" data-action="edit-account" data-id="${id}">✎ Editar conta</button><section class="section"><div class="section-title"><h2>Movimentos</h2></div><div class="card">${tx.slice(0,20).map(txRow).join('')||'<div class="empty">Sem movimentos.</div>'}</div></section>`)}
function categoriesModal(){return modalFrame('Categorias e tags',`<section><div class="section-title"><h2>Despesas</h2><button class="text-btn" data-action="new-category" data-kind="expense">＋ Nova</button></div><div class="card category-list">${state.categories.filter(c=>c.type==='expense'&&!c.archived).map(c=>`<button class="row" style="width:100%;background:transparent;border-left:0;border-right:0;border-top:0;text-align:left" data-action="edit-category" data-id="${c.id}"><span class="cat-icon" style="background:${c.color}">${c.emoji}</span><span class="row-main row-title">${esc(c.name)}</span><span>›</span></button>`).join('')}</div></section><section class="section"><div class="section-title"><h2>Receitas</h2><button class="text-btn" data-action="new-category" data-kind="income">＋ Nova</button></div><div class="card category-list">${state.categories.filter(c=>c.type==='income'&&!c.archived).map(c=>`<button class="row" style="width:100%;background:transparent;border-left:0;border-right:0;border-top:0;text-align:left" data-action="edit-category" data-id="${c.id}"><span class="cat-icon" style="background:${c.color}">${c.emoji}</span><span class="row-main row-title">${esc(c.name)}</span><span>›</span></button>`).join('')}</div></section><section class="section"><div class="section-title"><h2>Tags</h2></div><div class="card" style="padding:16px"><div class="chips">${state.tags.length?state.tags.map(t=>`<span class="chip active">#${esc(t.name)}</span>`).join(''):'<span class="tiny">As tags aparecem aqui quando as utilizares nos movimentos.</span>'}</div></div></section>`)}

function editTxModal(id){const t=state.tx.find(x=>x.id===id);if(!t)return'';if(t.type==='transfer')return modalFrame('Editar transferência',`<form id="edit-tx-form" class="form-grid"><input type="hidden" name="id" value="${id}"><input type="hidden" name="kind" value="transfer"><div class="field"><label>Valor</label><input class="input" name="amount" inputmode="decimal" value="${t.amount}" required></div><div class="field"><label>Descrição</label><input class="input" name="description" value="${esc(t.description)}" required></div><div class="inline-grid"><div class="field"><label>De</label><select class="select" name="fromAccountId">${state.accounts.map(a=>`<option value="${a.id}" ${a.id===t.fromAccountId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>Para</label><select class="select" name="toAccountId">${state.accounts.map(a=>`<option value="${a.id}" ${a.id===t.toAccountId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div></div><div class="field"><label>Data</label><input class="input" type="date" name="date" value="${t.date}" required></div><button class="save-btn" type="submit">Guardar alterações</button></form>`);const cats=state.categories.filter(c=>c.type===(t.type==='income'?'income':'expense')&&!c.archived);return modalFrame('Editar movimento',`<form id="edit-tx-form" class="form-grid"><input type="hidden" name="id" value="${id}"><input type="hidden" name="kind" value="${t.type}"><div class="field"><label>Valor</label><input class="input" name="amount" inputmode="decimal" value="${t.amount}" required></div><div class="field"><label>Descrição</label><input class="input" name="description" value="${esc(t.description)}" required></div><div class="inline-grid"><div class="field"><label>Categoria</label><select class="select" name="categoryId">${cats.map(c=>`<option value="${c.id}" ${c.id===t.categoryId?'selected':''}>${c.emoji} ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Conta</label><select class="select" name="accountId">${state.accounts.map(a=>`<option value="${a.id}" ${a.id===t.accountId?'selected':''}>${a.emoji} ${esc(a.name)}</option>`).join('')}</select></div></div><div class="field"><label>Data</label><input class="input" type="date" name="date" value="${t.date}" required></div><div class="field"><label>Loja / Empresa</label><input class="input" name="merchant" value="${esc(t.merchant||'')}"></div><div class="field"><label>Subcategoria</label><input class="input" name="subcategory" value="${esc(t.subcategory||'')}"></div><div class="field"><label>Tags</label><input class="input" name="tags" value="${esc((t.tags||[]).join(', '))}"></div><div class="field"><label>Nota</label><textarea name="note" rows="2">${esc(t.note||'')}</textarea></div>${t.type==='expense'?`<label class="toggle-row card"><span>🔁 Repetir este movimento</span><input class="switch" type="checkbox" name="recurring" ${t.recurring?.enabled?'checked':''}></label><div class="inline-grid"><div class="field"><label>Frequência</label><select class="select" name="recurringFrequency"><option value="mensal">Mensal</option></select></div><div class="field"><label>Próxima data</label><input class="input" type="date" name="recurringNextDate" value="${t.recurring?.nextDate||''}"></div></div>`:''}<button class="save-btn" type="submit">Guardar alterações</button></form>`)}
function splitModal(id){const t=state.tx.find(x=>x.id===id);if(!t)return'';const existing=t.splits?.length?t.splits:[{categoryId:t.categoryId,amount:t.amount},{categoryId:'',amount:''}];return modalFrame('Dividir despesa',`<p class="note">O total das partes deve ser exatamente ${money(t.amount)}.</p><form id="split-form" class="form-grid"><input type="hidden" name="id" value="${id}"><div id="split-rows">${existing.map((x,i)=>splitRowHtml(x,i)).join('')}</div><button type="button" class="secondary-btn" data-action="add-split-row">＋ Adicionar parte</button><button type="submit" class="save-btn">Guardar divisão</button></form>`)}
