function accountEditModal(id){const a=id?acct(id):null;return modalFrame(a?'Editar conta':'Nova conta',`<form id="account-form" class="form-grid"><input type="hidden" name="id" value="${a?.id||''}"><div class="inline-grid"><div class="field"><label>Emoji</label><input class="input" name="emoji" value="${esc(a?.emoji||'💳')}" maxlength="4"></div><div class="field"><label>Nome</label><input class="input" name="name" value="${esc(a?.name||'')}" required></div></div><div class="field"><label>Objetivo mensal de utilização (opcional)</label><input class="input" name="monthlyGoal" inputmode="decimal" value="${a?.monthlyGoal??''}" placeholder="Ex.: 500"></div><button class="save-btn" type="submit">Guardar conta</button>${a?`<button type="button" class="secondary-btn danger-btn" data-action="archive-account" data-id="${a.id}">Remover conta</button>`:''}</form>`)}
