function ruleEditModal(id,sourceTxId){const r=id?state.rules.find(x=>x.id===id):null,t=sourceTxId?state.tx.find(x=>x.id===sourceTxId):null;return modalFrame(r?'Editar regra':'Nova regra',`<form id="rule-form" class="form-grid"><input type="hidden" name="id" value="${r?.id||''}"><div class="field"><label>Quando a descrição contém</label><input class="input" name="match" value="${esc(r?.match||t?.merchant||t?.description||'')}" required></div><div class="field"><label>Nome Loja/Empresa (opcional)</label><input class="input" name="merchant" value="${esc(r?.merchant||t?.merchant||'')}"></div><div class="field"><label>Categoria</label><select class="select" name="categoryId"><option value="">Não alterar</option>${state.categories.filter(c=>c.type==='expense'&&!c.archived).map(c=>`<option value="${c.id}" ${(r?.categoryId||t?.categoryId)===c.id?'selected':''}>${c.emoji} ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Conta</label><select class="select" name="accountId"><option value="">Não alterar</option>${state.accounts.map(a=>`<option value="${a.id}" ${(r?.accountId||t?.accountId)===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><button class="save-btn" type="submit">Guardar regra</button>${r?`<button type="button" class="secondary-btn danger-btn" data-action="delete-rule" data-id="${r.id}">Apagar regra</button>`:''}</form>`)}
function summaryModal(k){const s=monthStats(k),[y,m]=k.split('-').map(Number),prev=new Date(y,m-2,1),ps=monthStats(`${prev.getFullYear()}-${String(prev.getMonth()+1).padStart(2,'0')}`),cats=Object.entries(categoryTotals(s.list)).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]),top=cats[0],changes=cats.map(([id,v])=>{const pv=categoryTotals(ps.list)[id]||0;return{id,v,d:v-pv}}).sort((a,b)=>Math.abs(b.d)-Math.abs(a.d)).slice(0,4);return modalFrame(`${monthName(y,m-1)} em resumo`,`<div class="card hero"><div class="eyebrow">🌸 Resumo mensal</div><div class="hero-value">${money(s.savings)} poupados</div><div class="hero-sub">Objetivo ${money(s.p.savingsGoal||0)} · ${s.savings>=(s.p.savingsGoal||0)?'✓ objetivo atingido':'objetivo não atingido'}</div></div><div class="hero-grid">${metric('Receitas',money(s.inc),'mint')}${metric('Despesas líquidas',money(s.exp),'pink')}${metric('Reembolsos',money(s.ref),'peach')}${metric('Maior categoria',top?cat(top[0])?.name||'—':'—','lilac')}</div><section class="section"><div class="section-title"><h2>O que mudou</h2></div><div class="card">${changes.map(x=>`<div class="row"><span class="cat-icon" style="background:${cat(x.id)?.color||'#eee'}">${cat(x.id)?.emoji||'•'}</span><span class="row-main row-title">${esc(cat(x.id)?.name||'Categoria')}</span><span class="row-amount ${x.d<=0?'positive':'negative'}">${x.d>=0?'+':''}${money(x.d)}</span></div>`).join('')||'<div class="empty">Sem comparação disponível.</div>'}</div></section>`)}
